package com.mbeddr.mpsutil.grammarcells.runtime;

/*Generated by MPS */

import java.util.List;
import java.util.Map;
import org.jetbrains.mps.openapi.language.SAbstractConcept;
import jetbrains.mps.internal.collections.runtime.MapSequence;
import java.util.HashMap;
import java.util.Set;
import jetbrains.mps.internal.collections.runtime.ListSequence;
import org.jetbrains.annotations.Nullable;
import java.util.ArrayList;
import jetbrains.mps.internal.collections.runtime.Sequence;
import jetbrains.mps.lang.smodel.generator.smodelAdapter.SConceptOperations;
import jetbrains.mps.lang.smodel.generator.smodelAdapter.SNodeOperations;
import jetbrains.mps.internal.collections.runtime.SetSequence;
import java.util.HashSet;
import java.util.Objects;

/**
 * 
 * Parses a list of tokens against the rules of the visible grammar cells languages.
 * Unlike the recursive descent in Parser, which tries every way of distributing the tokens
 * over the symbols of a rule and re-parses the same tokens once per distribution, this is a
 * chart parser (Earley) - every rule that can start at an input position is entered into the
 * chart once, and a subtree parsed for one rule is reused by every other rule that asks for
 * the same tokens. That makes the work polynomial in the number of tokens instead of
 * exponential, and it removes the recursion depth limit the descent needed.
 * The chart holds one ChartState per input position, with the items that end there. An item
 * is advanced either by a single token - a constant, a property, a reference, or a child
 * node that was not destructed - or by a completed item of another rule. Priority and
 * associativity are checked where a child is attached to its parent, which is the same
 * check the descent does before it descends, so both accept the same trees.
 */
public class ChartParser {

  private Parser myParser;
  private IToken[] myTokens;
  private int myLength;
  private List<IRule> myRules;
  private Map<IToken, SAbstractConcept> myOriginalConcepts;

  private Map<Integer, ChartState> myStates = MapSequence.fromMap(new HashMap<Integer, ChartState>());
  private Map<IRule, Integer> myRuleRanks = MapSequence.fromMap(new HashMap<IRule, Integer>());
  private Map<IRule, ISymbol[]> myRuleSymbols = MapSequence.fromMap(new HashMap<IRule, ISymbol[]>());
  private Map<SAbstractConcept, List<IRule>> myRulesByConcept = MapSequence.fromMap(new HashMap<SAbstractConcept, List<IRule>>());
  private Map<SAbstractConcept, Set<IRule>> myRuleSetsByConcept = MapSequence.fromMap(new HashMap<SAbstractConcept, Set<IRule>>());
  private Map<ISymbol, Boolean[]> myMatches = MapSequence.fromMap(new HashMap<ISymbol, Boolean[]>());
  private Map<String, Boolean> myAllowedChildren = MapSequence.fromMap(new HashMap<String, Boolean>());
  private Map<String, SAbstractConcept> myPreferredConcepts = MapSequence.fromMap(new HashMap<String, SAbstractConcept>());

  /**
   * 'rules' are the rules to parse with, best first - where the input is ambiguous, the rule
   * that comes first wins. 'originalConcepts' says which concept a token was read from,
   * which is what keeps an edited node at its concept.
   */
  public ChartParser(Parser parser, List<IToken> tokens, List<IRule> rules, Map<IToken, SAbstractConcept> originalConcepts) {
    myParser = parser;
    myRules = rules;
    myOriginalConcepts = originalConcepts;
    myLength = ListSequence.fromList(tokens).count();
    myTokens = new IToken[myLength];
    int tokenIndex = 0;
    for (IToken token : ListSequence.fromList(tokens)) {
      myTokens[tokenIndex] = token;
      tokenIndex++;
    }
    int rank = 0;
    for (IRule rule : ListSequence.fromList(rules)) {
      MapSequence.fromMap(myRuleRanks).put(rule, rank);
      rank++;
    }
  }

  /**
   * The parse tree covering all tokens, or null if there is none.
   */
  @Nullable
  public PNode parse(@Nullable SAbstractConcept expectedConcept) {
    if (myLength == 0) {
      return null;
    }
    buildChart(expectedConcept);
    List<ChartItem> candidates = ListSequence.fromList(new ArrayList<ChartItem>());
    for (ChartItem item : ListSequence.fromList(getState(myLength).getItems())) {
      if (item.getStart() == 0 && item.isComplete()) {
        ListSequence.fromList(candidates).addElement(item);
      }
    }
    for (ChartItem candidate : ListSequence.fromList(candidates).sort((a, b) -> compareItems(a, b), true)) {
      PNode tree = buildTree(candidate);
      if (tree != null) {
        return tree;
      }
    }
    return null;
  }

  protected void buildChart(@Nullable SAbstractConcept expectedConcept) {
    for (IRule rule : ListSequence.fromList(getRulesFor(expectedConcept))) {
      addItem(rule, 0, 0, 0);
    }
    for (int position = 0; position <= myLength; position++) {
      ChartState state = getState(position);
      while (state.hasPending()) {
        for (ChartItem item : ListSequence.fromList(state.takePending())) {
          processItem(item, position);
        }
      }
    }
  }

  /**
   * Either the item is done and gets attached to the parents that were waiting for it, or
   * its next symbol is matched against the token at 'position' and, when that symbol is a
   * child, the rules that can produce it are entered at 'position'.
   */
  protected void processItem(ChartItem item, int position) {
    if (item.isComplete()) {
      complete(item);
      return;
    }
    ISymbol symbol = getSymbol(item.getRule(), item.getDot());
    if (position < myLength && matches(symbol, position)) {
      advance(item, null, position + 1);
    }
    if (isChildSymbol(symbol)) {
      SAbstractConcept expectedConcept = symbol.getOutputConcept();
      ChartState state = getState(position);
      state.addWaiting(expectedConcept, item);
      if (!(state.isPredicted(expectedConcept))) {
        state.setPredicted(expectedConcept);
        for (IRule rule : ListSequence.fromList(getRulesFor(expectedConcept))) {
          addItem(rule, 0, position, position);
        }
      }
    }
  }

  /**
   * Attaches a finished subtree to every item that was waiting for it where it started. That
   * state is never written to again, so the lists read here do not change while they are
   * read.
   */
  protected void complete(ChartItem item) {
    ChartState startState = getState(item.getStart());
    IRule rule = item.getRule();
    for (SAbstractConcept expectedConcept : Sequence.fromIterable(startState.getExpectedConcepts())) {
      if (!(isRuleFor(rule, expectedConcept))) {
        continue;
      }
      for (ChartItem waiting : ListSequence.fromList(startState.getWaiting(expectedConcept))) {
        if (!(isAllowedChild(waiting.getRule(), waiting.getDot(), rule))) {
          continue;
        }
        advance(waiting, item, item.getEnd());
      }
    }
  }

  /**
   * Moves 'item' past its next symbol, matched either by the completed 'child' or, when that
   * is null, by the single token ending at 'end'.
   */
  protected void advance(ChartItem item, @Nullable ChartItem child, int end) {
    ChartItem next = addItem(item.getRule(), item.getDot() + 1, item.getStart(), end);
    next.addLink(new ChartLink(item, child));
  }

  protected ChartItem addItem(IRule rule, int dot, int start, int end) {
    myParser.countDown();
    ChartState state = getState(end);
    String key = "" + MapSequence.fromMap(myRuleRanks).get(rule) + ":" + dot + ":" + start;
    ChartItem existing = state.findItem(key);
    if (existing != null) {
      return existing;
    }
    ChartItem item = new ChartItem(rule, dot, start, end);
    state.addItem(key, item);
    return item;
  }

  protected ChartState getState(int position) {
    ChartState state = MapSequence.fromMap(myStates).get(position);
    if (state == null) {
      state = new ChartState();
      MapSequence.fromMap(myStates).put(position, state);
    }
    return state;
  }

  /**
   * True for a symbol that is parsed from a whole range of tokens, that is for a child cell.
   * A reference is not one - it reads a single token even though it has an output concept.
   */
  protected boolean isChildSymbol(ISymbol symbol) {
    return !(symbol.hasFixedTokenNumber()) && symbol.getOutputConcept() != null;
  }

  /**
   * Whether the symbol accepts the token at 'tokenIndex'. Checking a property runs its
   * constraints, so the answer is remembered.
   */
  protected boolean matches(ISymbol symbol, int tokenIndex) {
    Boolean[] cached = MapSequence.fromMap(myMatches).get(symbol);
    if (cached == null) {
      cached = new Boolean[myLength];
      MapSequence.fromMap(myMatches).put(symbol, cached);
    }
    if (cached[tokenIndex] == null) {
      cached[tokenIndex] = symbol.matches(myTokens[tokenIndex]);
    }
    return cached[tokenIndex];
  }

  protected ISymbol getSymbol(IRule rule, int index) {
    ISymbol[] symbols = MapSequence.fromMap(myRuleSymbols).get(rule);
    if (symbols == null) {
      symbols = new ISymbol[ListSequence.fromList(rule.getSymbols()).count()];
      int symbolIndex = 0;
      for (ISymbol symbol : ListSequence.fromList(rule.getSymbols())) {
        symbols[symbolIndex] = symbol;
        symbolIndex++;
      }
      MapSequence.fromMap(myRuleSymbols).put(rule, symbols);
    }
    return symbols[index];
  }

  /**
   * The rules that can produce 'expectedConcept', in the order they should be tried.
   */
  protected List<IRule> getRulesFor(@Nullable final SAbstractConcept expectedConcept) {
    if (expectedConcept == null) {
      return myRules;
    }
    List<IRule> rules = MapSequence.fromMap(myRulesByConcept).get(expectedConcept);
    if (rules == null) {
      rules = ListSequence.fromList(myRules).where((it) -> SConceptOperations.isSubConceptOf(SNodeOperations.asSConcept(it.getOutputConcept()), SNodeOperations.asSConcept(expectedConcept))).toList();
      MapSequence.fromMap(myRulesByConcept).put(expectedConcept, rules);
      MapSequence.fromMap(myRuleSetsByConcept).put(expectedConcept, SetSequence.fromSetWithValues(new HashSet<IRule>(), rules));
    }
    return rules;
  }

  protected boolean isRuleFor(IRule rule, SAbstractConcept expectedConcept) {
    getRulesFor(expectedConcept);
    return SetSequence.fromSet(MapSequence.fromMap(myRuleSetsByConcept).get(expectedConcept)).contains(rule);
  }

  /**
   * Whether 'childRule' may be used for the symbol at 'symbolIndex' of 'parentRule'. This is
   * the priority and associativity check of the recursive descent, asked here instead of
   * before descending. It depends on the two rules and the position only, so it is cached.
   */
  protected boolean isAllowedChild(IRule parentRule, int symbolIndex, IRule childRule) {
    String key = "" + MapSequence.fromMap(myRuleRanks).get(parentRule) + ":" + symbolIndex + ":" + MapSequence.fromMap(myRuleRanks).get(childRule);
    Boolean cached = MapSequence.fromMap(myAllowedChildren).get(key);
    if (cached != null) {
      return cached;
    }
    boolean allowed = calculateAllowedChild(parentRule, symbolIndex, childRule);
    MapSequence.fromMap(myAllowedChildren).put(key, allowed);
    return allowed;
  }

  protected boolean calculateAllowedChild(IRule parentRule, int symbolIndex, IRule childRule) {
    ISymbol symbol = getSymbol(parentRule, symbolIndex);
    SAbstractConcept expectedConcept = symbol.getOutputConcept();
    boolean canBeRotated = myParser.canBeRotated(childRule, new SymbolInRule(parentRule, symbol, symbolIndex));
    boolean isSamePriority = parentRule.getPriority() == childRule.getPriority() && parentRule.isLeftAssociative() == childRule.isLeftAssociative();

    if (isSamePriority && canBeRotated) {
      int allowedIndex = -1;
      int sameConceptCount = 0;
      int index = 0;
      for (ISymbol parentSymbol : ListSequence.fromList(parentRule.getSymbols())) {
        SAbstractConcept outputConcept = parentSymbol.getOutputConcept();
        if (outputConcept != null && SConceptOperations.isExactly(SNodeOperations.asSConcept(outputConcept), SNodeOperations.asSConcept(expectedConcept))) {
          sameConceptCount++;
          if (allowedIndex == -1 || !(parentRule.isLeftAssociative())) {
            allowedIndex = index;
          }
        }
        index++;
      }
      if (sameConceptCount > 1 && symbolIndex != allowedIndex) {
        // In case of left associativity, the same concept is allowed only on the left side.
        // For example, for the input 1+2+3, there are the two possible trees 1+(2+3) and (1+2)+3.
        // We want the second one.
        return false;
      }
    }

    if (canBeRotated && parentRule.getPriority() > childRule.getPriority()) {
      // A * is not allowed as the parent of a +, because for the input 1+2*3 we don't want (1+2)*3
      return false;
    }

    return true;
  }

  /**
   * Builds the tree of a completed item, choosing the best derivation where the input is
   * ambiguous. The result is kept on the item, so a subtree shared by several rules is
   * built once.
   */
  @Nullable
  protected PNode buildTree(ChartItem item) {
    if (item.getTree() != null) {
      return item.getTree();
    }
    if (item.isBuilding()) {
      // two rules that produce each other over the same tokens
      return null;
    }
    item.setBuilding(true);
    try {
      List<PNode> children = buildChildren(item);
      if (children == null) {
        return null;
      }
      PNode tree = new PNode(item.getRule());
      for (PNode child : ListSequence.fromList(children)) {
        tree.addChild(child);
      }
      item.setTree(tree);
      return tree;
    } finally {
      item.setBuilding(false);
    }
  }

  /**
   * The subtrees of the symbols matched so far, in the order of the symbols. Walks the links
   * back to the start of the rule, taking the best link that can be built at each step.
   */
  @Nullable
  protected List<PNode> buildChildren(ChartItem item) {
    if (item.getDot() == 0) {
      return ListSequence.fromList(new ArrayList<PNode>());
    }
    for (ChartLink link : ListSequence.fromList(sortLinks(item))) {
      PNode child = buildLink(item, link);
      if (child == null) {
        continue;
      }
      List<PNode> children = buildChildren(link.getPrev());
      if (children == null) {
        continue;
      }
      ListSequence.fromList(children).addElement(child);
      return children;
    }
    return null;
  }

  @Nullable
  protected PNode buildLink(ChartItem item, ChartLink link) {
    ISymbol symbol = getSymbol(item.getRule(), item.getDot() - 1);
    if (link.getChild() == null) {
      return new PNode(myTokens[item.getEnd() - 1], symbol);
    }
    PNode child = buildTree(link.getChild());
    if (child == null) {
      return null;
    }
    child.setSymbol(symbol);
    return child;
  }

  protected List<ChartLink> sortLinks(final ChartItem item) {
    List<ChartLink> links = item.getLinks();
    if (ListSequence.fromList(links).count() < 2) {
      return links;
    }
    return ListSequence.fromList(links).sort((a, b) -> compareLinks(item, a, b), true).toList();
  }

  /**
   * Orders the ways one symbol can be matched - an untouched node first, then the rule the
   * caller preferred, and finally by token count. A left associative rule leaves as few
   * tokens as possible to its last symbol, so that 1+2+3 becomes (1+2)+3.
   */
  protected int compareLinks(ChartItem item, ChartLink a, ChartLink b) {
    int result = linkPreference(a) - linkPreference(b);
    if (result != 0) {
      return result;
    }
    result = linkRank(a) - linkRank(b);
    if (result != 0) {
      return result;
    }
    int lengthA = linkLength(a);
    int lengthB = linkLength(b);
    return (item.getRule().isLeftAssociative() ? lengthA - lengthB : lengthB - lengthA);
  }

  protected int linkPreference(ChartLink link) {
    if (link.getChild() == null) {
      return 0;
    }
    return (isPreferred(link.getChild()) ? 0 : 1);
  }

  protected int linkRank(ChartLink link) {
    if (link.getChild() == null) {
      return -1;
    }
    return MapSequence.fromMap(myRuleRanks).get(link.getChild().getRule());
  }

  protected int linkLength(ChartLink link) {
    if (link.getChild() == null) {
      return 1;
    }
    return link.getChild().getEnd() - link.getChild().getStart();
  }

  protected int compareItems(ChartItem a, ChartItem b) {
    int result = ((isPreferred(a) ? 0 : 1)) - ((isPreferred(b) ? 0 : 1));
    if (result != 0) {
      return result;
    }
    return MapSequence.fromMap(myRuleRanks).get(a.getRule()) - MapSequence.fromMap(myRuleRanks).get(b.getRule());
  }

  /**
   * True if the item produces the concept its tokens were read from.
   */
  protected boolean isPreferred(ChartItem item) {
    SAbstractConcept preferredConcept = getPreferredConcept(item.getStart(), item.getEnd());
    return preferredConcept != null && Objects.equals(preferredConcept, item.getRule().getOutputConcept());
  }

  /**
   * The concept the tokens between 'start' and 'end' were read from, if they all come from
   * nodes of one concept. Rules producing it are preferred, which is what keeps a node at
   * its concept while it is being edited.
   */
  @Nullable
  protected SAbstractConcept getPreferredConcept(int start, int end) {
    String key = "" + start + ":" + end;
    if (MapSequence.fromMap(myPreferredConcepts).containsKey(key)) {
      return MapSequence.fromMap(myPreferredConcepts).get(key);
    }
    SAbstractConcept result = null;
    for (int index = start; index < end; index++) {
      SAbstractConcept original = MapSequence.fromMap(myOriginalConcepts).get(myTokens[index]);
      if (original == null) {
        continue;
      }
      if (result == null) {
        result = original;
      } else if (!(Objects.equals(result, original))) {
        result = null;
        break;
      }
    }
    MapSequence.fromMap(myPreferredConcepts).put(key, result);
    return result;
  }

  /**
   * How many items the chart holds. This is the work the parse did, for diagnostics.
   */
  public int getItemCount() {
    int result = 0;
    for (int position = 0; position <= myLength; position++) {
      result += ListSequence.fromList(getState(position).getItems()).count();
    }
    return result;
  }
}
